begin;

do $repair$
declare
  r record;
  current_row public.academy_lesson_script%rowtype;
  touched integer := 0;
begin
  if (select count(*) from public.academy_lessons where code in ('L2','L3','L6')) <> 3 then
    raise exception 'academy baseline repair: lessons L2/L3/L6 non univoche o assenti';
  end if;

  for r in
    select * from (values
    ('L2', 'ac7e1c59-a555-4679-bda9-82893b7c3366'::uuid, 6, 'konoha', null::boolean, convert_from(decode('','base64'),'UTF8'), 'd424c364f1b48dc82bda6868264b92d0'),
    ('L2', 'ac7e1c59-a555-4679-bda9-82893b7c3366'::uuid, 7, 'konoha', null::boolean, convert_from(decode('','base64'),'UTF8'), '35342fbfe2c973708ddf88af7def6b18'),
    ('L2', 'ac7e1c59-a555-4679-bda9-82893b7c3366'::uuid, 8, 'konoha', null::boolean, convert_from(decode('','base64'),'UTF8'), 'bd0101e13020e1b24e80570f2e19cfa5'),
    ('L2', 'ac7e1c59-a555-4679-bda9-82893b7c3366'::uuid, 6, 'suna', null::boolean, convert_from(decode('','base64'),'UTF8'), 'd35fd754dfc826c3fd987867e9cc6577'),
    ('L2', 'ac7e1c59-a555-4679-bda9-82893b7c3366'::uuid, 7, 'suna', null::boolean, convert_from(decode('','base64'),'UTF8'), 'a2e7c716864cfbc45539c43a86033bd5'),
    ('L2', 'ac7e1c59-a555-4679-bda9-82893b7c3366'::uuid, 8, 'suna', null::boolean, convert_from(decode('','base64'),'UTF8'), '345a08190d722c85f6c0f9497e0ade38'),
    ('L3', '346757f7-c452-4e16-910e-5a290addb530'::uuid, 5, 'konoha', null::boolean, convert_from(decode('','base64'),'UTF8'), '0486b8017c0f79f50bd509b4642988f6'),
    ('L3', '346757f7-c452-4e16-910e-5a290addb530'::uuid, 6, 'konoha', null::boolean, convert_from(decode('','base64'),'UTF8'), '25053bf7d2b89bbcfcfc0c2c37baca53'),
    ('L3', '346757f7-c452-4e16-910e-5a290addb530'::uuid, 5, 'suna', null::boolean, convert_from(decode('','base64'),'UTF8'), 'fadc8c780bc134f2ed4558418d1d9759'),
    ('L3', '346757f7-c452-4e16-910e-5a290addb530'::uuid, 6, 'suna', null::boolean, convert_from(decode('','base64'),'UTF8'), '5b7e35c0eceea5c285c3f4ebad3e730d'),
    ('L6', 'abd84cda-0409-4d2d-804e-09ea2210a531'::uuid, 5, 'konoha', null::boolean, convert_from(decode('KlJhY2NvZ2xpZSBpbCBnZXNzbyBlIGxvIHBvc2EgaW4gb3JkaW5lIHN1bGxhIGNhdHRlZHJhLiogwqtSaWZsZXNzaSBkYSBtaWdsaW9yYXJlLCBtYSBsYSBiYXNlIGMnw6guIExhIFNvc3RpdHV6aW9uZSDDqCB2b3N0cmEuIENvbiBxdWVzdGEgY29tcGxldGF0ZSBpbCBwcm9ncmFtbWEuIFJlc3RhIGwnZXNhbWUuwrs=','base64'),'UTF8'), '414d851a3d510952190665f00284e977'),
    ('L6', 'abd84cda-0409-4d2d-804e-09ea2210a531'::uuid, 5, 'suna', null::boolean, convert_from(decode('','base64'),'UTF8'), 'dd665a664a36d6344707e06d4a6a4415')
    ) as v(code, lesson_id, step, village, valuta, body, body_md5)
  loop
    if not exists (select 1 from public.academy_lessons l where l.id=r.lesson_id and l.code=r.code) then
      raise exception 'academy baseline repair: lesson identity drift %/%', r.code, r.lesson_id;
    end if;
    if md5(r.body) <> r.body_md5 then
      raise exception 'academy baseline repair: embedded body checksum mismatch %/%/%', r.code, r.village, r.step;
    end if;

    select s.* into current_row
      from public.academy_lesson_script s
     where s.lesson_id=r.lesson_id and s.step=r.step and s.village=r.village
     for update;

    if found then
      if current_row.body is distinct from r.body or current_row.valuta is distinct from r.valuta then
        raise exception 'academy baseline repair: concurrent row drift %/%/%', r.code, r.village, r.step;
      end if;
    else
      insert into public.academy_lesson_script(lesson_id,step,body,village,valuta)
      values(r.lesson_id,r.step,r.body,r.village,r.valuta);
      touched := touched + 1;
    end if;
  end loop;

  if (select count(*) from public.academy_lesson_script) <> 74 then
    raise exception 'academy baseline repair: expected exactly 74 rows, found %',
      (select count(*) from public.academy_lesson_script);
  end if;
  if touched not in (0,12) then
    raise exception 'academy baseline repair: partial baseline accepted unexpectedly (% rows)', touched;
  end if;
end
$repair$;

commit;
